(1394, '_wpforms_transient_wpforms_template_batch_4352e8d49737cb4303801db8712728cb', 'a:4:{s:9:\"templates\";a:12:{i:0;s:1990:\"<div class=\"wpforms-template\"\n	id=\"wpforms-template-conference-registration-form-template\"\n	>\n\n	<div class=\"wpforms-template-thumbnail\">\n					<img src=\"https://wpforms.com/templates/wp-content/uploads/templates/thumb/be32b8cc1eb80419086b4b282acf6d4b.jpg\" alt=\"Conference Registration Form Template\" loading=\"lazy\" />\n			</div>\n\n	<!-- As requirement for Lists.js library data attribute slug is used in classes list. -->\n	<h3 class=\"wpforms-template-name categories has-access favorite slug subcategories fields\"\n		data-categories=\"registrations,event-planning\"\n		data-subcategories=\"business-registration-forms\"\n		data-fields=\"This field is not editable,Name,Email,Multiple Choice,Checkboxes,Paragraph Text,textarea,radio,choice,user,first,last\"\n		data-has-access=\"1\"\n		data-favorite=\"\"\n		data-slug=\"conference-registration-form-template\"\n	>\n		Conference Registration Form	</h3>\n\n			<span class=\"wpforms-template-favorite\">\n							<i class=\"fa fa-heart wpforms-hidden\" title=\"Remove from Favorites\"></i>\n				<i class=\"fa fa-heart-o \" title=\"Mark as Favorite\"></i>\n					</span>\n	\n	\n	<p class=\'wpforms-template-desc\'>\n		Collect attendee information to plan and manage your next conference event perfectly.	</p>\n\n			<div class=\"wpforms-template-buttons\">\n			<a href=\"#\" class=\"wpforms-template-select wpforms-btn wpforms-btn-md wpforms-btn-orange\"\n				data-template-name-raw=\"Conference Registration Form\"\n				data-template=\"e5987a41fb12ff57c5f125c8cf2963a5\"\n				data-slug=\"conference-registration-form-template\"\n				data-create-url=\"\"\n								>\n				Use Template			</a>\n\n							<a class=\"wpforms-template-demo wpforms-btn wpforms-btn-md wpforms-btn-light-grey\"\n					href=\"https://wpforms.com/templates/conference-registration-form-template/?utm_campaign=liteplugin&#038;utm_source=WordPress&#038;utm_medium=builder-templates&#038;utm_content=Conference%20Registration%20Form&#038;utm_locale=en_US\"\n					target=\"_blank\" rel=\"noopener noreferrer\">\n					View Demo				</a>\n			\n					</div>\n	\n</div>\n\";i:1;s:1824:\"<div class=\"wpforms-template\"\n	id=\"wpforms-template-grade-book-form-template\"\n	>\n\n	<div class=\"wpforms-template-thumbnail\">\n					<img src=\"https://wpforms.com/templates/wp-content/uploads/templates/thumb/47b0f714a00816dd48acf313b02df132.jpg\" alt=\"Grade Book Form Template\" loading=\"lazy\" />\n			</div>\n\n	<!-- As requirement for Lists.js library data attribute slug is used in classes list. -->\n	<h3 class=\"wpforms-template-name categories has-access favorite slug subcategories fields\"\n		data-categories=\"education,nonprofit\"\n		data-subcategories=\"evaluation-forms\"\n		data-fields=\"Name,Single Line Text,Dropdown,Paragraph Text,Email,textarea,choice,user,first,last\"\n		data-has-access=\"1\"\n		data-favorite=\"\"\n		data-slug=\"grade-book-form-template\"\n	>\n		Grade Book Form	</h3>\n\n			<span class=\"wpforms-template-favorite\">\n							<i class=\"fa fa-heart wpforms-hidden\" title=\"Remove from Favorites\"></i>\n				<i class=\"fa fa-heart-o \" title=\"Mark as Favorite\"></i>\n					</span>\n	\n	\n	<p class=\'wpforms-template-desc\'>\n		Collect student information and all assignments into one convenient location.	</p>\n\n			<div class=\"wpforms-template-buttons\">\n			<a href=\"#\" class=\"wpforms-template-select wpforms-btn wpforms-btn-md wpforms-btn-orange\"\n				data-template-name-raw=\"Grade Book Form\"\n				data-template=\"30bc5bd5cc3d044b0a5cab73b784df2b\"\n				data-slug=\"grade-book-form-template\"\n				data-create-url=\"\"\n								>\n				Use Template			</a>\n\n							<a class=\"wpforms-template-demo wpforms-btn wpforms-btn-md wpforms-btn-light-grey\"\n					href=\"https://wpforms.com/templates/grade-book-form-template/?utm_campaign=liteplugin&#038;utm_source=WordPress&#038;utm_medium=builder-templates&#038;utm_content=Grade%20Book%20Form&#038;utm_locale=en_US\"\n					target=\"_blank\" rel=\"noopener noreferrer\">\n					View Demo				</a>\n			\n					</div>\n	\n</div>\n\";i:2;s:1888:\"<div class=\"wpforms-template\"\n	id=\"wpforms-template-lead-magnet-download-form-template\"\n	>\n\n	<div class=\"wpforms-template-thumbnail\">\n					<img src=\"https://wpforms.com/templates/wp-content/uploads/templates/thumb/237e149dcb4731d2359b112b240908f6.jpg\" alt=\"Lead Magnet Download Form Template\" loading=\"lazy\" />\n			</div>\n\n	<!-- As requirement for Lists.js library data attribute slug is used in classes list. -->\n	<h3 class=\"wpforms-template-name categories has-access favorite slug subcategories fields\"\n		data-categories=\"marketing\"\n		data-subcategories=\"lead-capture-forms\"\n		data-fields=\"This field is not editable,Name,Email,Dropdown,Checkboxes,choice,user,first,last\"\n		data-has-access=\"1\"\n		data-favorite=\"\"\n		data-slug=\"lead-magnet-download-form-template\"\n	>\n		Lead Magnet Download Form	</h3>\n\n			<span class=\"wpforms-template-favorite\">\n							<i class=\"fa fa-heart wpforms-hidden\" title=\"Remove from Favorites\"></i>\n				<i class=\"fa fa-heart-o \" title=\"Mark as Favorite\"></i>\n					</span>\n	\n	\n	<p class=\'wpforms-template-desc\'>\n		Offer an instant download when your visitor submits this contact form.	</p>\n\n			<div class=\"wpforms-template-buttons\">\n			<a href=\"#\" class=\"wpforms-template-select wpforms-btn wpforms-btn-md wpforms-btn-orange\"\n				data-template-name-raw=\"Lead Magnet Download Form\"\n				data-template=\"500f3dc72d8a43c905e28c0d7ba79615\"\n				data-slug=\"lead-magnet-download-form-template\"\n				data-create-url=\"\"\n								>\n				Use Template			</a>\n\n							<a class=\"wpforms-template-demo wpforms-btn wpforms-btn-md wpforms-btn-light-grey\"\n					href=\"https://wpforms.com/templates/lead-magnet-download-form-template/?utm_campaign=liteplugin&#038;utm_source=WordPress&#038;utm_medium=builder-templates&#03